CREATE TABLE IF NOT EXISTS tenants(id varchar(36) PRIMARY KEY,name varchar(200) UNIQUE NOT NULL,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS roles(id varchar(36) PRIMARY KEY,name varchar(50) UNIQUE NOT NULL);
CREATE TABLE IF NOT EXISTS users(id varchar(36) PRIMARY KEY,tenant_id varchar(36) NOT NULL REFERENCES tenants(id),email varchar(320) UNIQUE NOT NULL,full_name varchar(200) NOT NULL,password_hash varchar(500) NOT NULL,is_active boolean NOT NULL DEFAULT true,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS user_roles(id varchar(36) PRIMARY KEY,user_id varchar(36) NOT NULL REFERENCES users(id),role_id varchar(36) NOT NULL REFERENCES roles(id),UNIQUE(user_id,role_id));
CREATE TABLE IF NOT EXISTS invoices(id varchar(36) PRIMARY KEY,tenant_id varchar(36) NOT NULL REFERENCES tenants(id),created_by varchar(36) NOT NULL REFERENCES users(id),status varchar(40) NOT NULL DEFAULT 'EXTRACTED',source_version varchar(100) NOT NULL DEFAULT 'document-service@2.0.0',correlation_id varchar(36) NOT NULL,invoice_number varchar(100),invoice_symbol varchar(100),seller_tax_code varchar(30),document jsonb NOT NULL,normalized_data jsonb NOT NULL,validation_result jsonb,reconciliation_result jsonb,anomaly_result jsonb,risk_result jsonb,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX IF NOT EXISTS ix_invoices_tenant ON invoices(tenant_id);CREATE INDEX IF NOT EXISTS ix_invoices_identity ON invoices(tenant_id,seller_tax_code,invoice_symbol,invoice_number);
CREATE TABLE IF NOT EXISTS invoice_files(id varchar(36) PRIMARY KEY,tenant_id varchar(36) NOT NULL REFERENCES tenants(id),invoice_id varchar(36) NOT NULL REFERENCES invoices(id),storage_key varchar(1000) NOT NULL,sha256 varchar(64) NOT NULL,content_type varchar(100) NOT NULL,size_bytes integer NOT NULL,created_by varchar(36) NOT NULL REFERENCES users(id),source_version varchar(100) NOT NULL,correlation_id varchar(36) NOT NULL,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS account_files(id varchar(36) PRIMARY KEY,tenant_id varchar(36) NOT NULL REFERENCES tenants(id),owner_id varchar(36) NOT NULL REFERENCES users(id),filename varchar(500) NOT NULL,storage_key varchar(1000) UNIQUE NOT NULL,sha256 varchar(64) NOT NULL,content_type varchar(150) NOT NULL,size_bytes integer NOT NULL,category varchar(40) NOT NULL DEFAULT 'other',description text NOT NULL DEFAULT '',tags jsonb NOT NULL DEFAULT '[]'::jsonb,correlation_id varchar(36) NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX IF NOT EXISTS ix_account_files_owner ON account_files(tenant_id,owner_id,created_at DESC);
CREATE TABLE IF NOT EXISTS invoice_lines(id varchar(36) PRIMARY KEY,tenant_id varchar(36) NOT NULL REFERENCES tenants(id),invoice_id varchar(36) NOT NULL REFERENCES invoices(id),line_number integer NOT NULL,data jsonb NOT NULL,created_by varchar(36) NOT NULL REFERENCES users(id),source_version varchar(100) NOT NULL,correlation_id varchar(36) NOT NULL,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS extraction_runs(id varchar(36) PRIMARY KEY,tenant_id varchar(36) NOT NULL REFERENCES tenants(id),invoice_id varchar(36) NOT NULL REFERENCES invoices(id),status varchar(30) NOT NULL,result jsonb NOT NULL,created_by varchar(36) NOT NULL REFERENCES users(id),source_version varchar(100) NOT NULL,correlation_id varchar(36) NOT NULL,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS extracted_fields(id varchar(36) PRIMARY KEY,tenant_id varchar(36) NOT NULL REFERENCES tenants(id),extraction_run_id varchar(36) NOT NULL REFERENCES extraction_runs(id),field_name varchar(100) NOT NULL,value jsonb NOT NULL,confidence varchar(20) NOT NULL,created_by varchar(36) NOT NULL REFERENCES users(id),source_version varchar(100) NOT NULL,correlation_id varchar(36) NOT NULL,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS field_corrections(id varchar(36) PRIMARY KEY,tenant_id varchar(36) NOT NULL REFERENCES tenants(id),invoice_id varchar(36) NOT NULL REFERENCES invoices(id),field_name varchar(100) NOT NULL,old_value jsonb NOT NULL,new_value jsonb NOT NULL,reason text NOT NULL,created_by varchar(36) NOT NULL REFERENCES users(id),source_version varchar(100) NOT NULL DEFAULT 'human-correction@2.0.0',correlation_id varchar(36) NOT NULL,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS rule_results(id varchar(36) PRIMARY KEY,tenant_id varchar(36) NOT NULL REFERENCES tenants(id),invoice_id varchar(36) NOT NULL REFERENCES invoices(id),result jsonb NOT NULL,created_by varchar(36) NOT NULL REFERENCES users(id),source_version varchar(100) NOT NULL,correlation_id varchar(36) NOT NULL,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS reconciliation_runs(id varchar(36) PRIMARY KEY,tenant_id varchar(36) NOT NULL REFERENCES tenants(id),invoice_id varchar(36) NOT NULL REFERENCES invoices(id),result jsonb NOT NULL,created_by varchar(36) NOT NULL REFERENCES users(id),source_version varchar(100) NOT NULL DEFAULT 'reconciliation@2.0.0',correlation_id varchar(36) NOT NULL,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS model_predictions(id varchar(36) PRIMARY KEY,tenant_id varchar(36) NOT NULL REFERENCES tenants(id),invoice_id varchar(36) NOT NULL REFERENCES invoices(id),result jsonb NOT NULL,created_by varchar(36) NOT NULL REFERENCES users(id),source_version varchar(100) NOT NULL,correlation_id varchar(36) NOT NULL,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS risk_assessments(id varchar(36) PRIMARY KEY,tenant_id varchar(36) NOT NULL REFERENCES tenants(id),invoice_id varchar(36) NOT NULL REFERENCES invoices(id),result jsonb NOT NULL,created_by varchar(36) NOT NULL REFERENCES users(id),source_version varchar(100) NOT NULL DEFAULT 'risk-aggregator@2.0.0',correlation_id varchar(36) NOT NULL,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS review_tasks(id varchar(36) PRIMARY KEY,tenant_id varchar(36) NOT NULL REFERENCES tenants(id),invoice_id varchar(36) NOT NULL REFERENCES invoices(id),status varchar(30) NOT NULL DEFAULT 'PENDING',assigned_role varchar(50) NOT NULL DEFAULT 'accountant_lead',source_version varchar(100) NOT NULL DEFAULT 'review-workflow@2.0.0',correlation_id varchar(36) NOT NULL,created_by varchar(36) NOT NULL REFERENCES users(id),created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS review_decisions(id varchar(36) PRIMARY KEY,review_id varchar(36) NOT NULL REFERENCES review_tasks(id),tenant_id varchar(36) NOT NULL REFERENCES tenants(id),decision varchar(30) NOT NULL,comment text NOT NULL,created_by varchar(36) NOT NULL REFERENCES users(id),source_version varchar(100) NOT NULL DEFAULT 'review-workflow@2.0.0',correlation_id varchar(36) NOT NULL,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS audit_events(id varchar(36) PRIMARY KEY,sequence integer NOT NULL,tenant_id varchar(36) NOT NULL REFERENCES tenants(id),actor_id varchar(36) NOT NULL REFERENCES users(id),action varchar(100) NOT NULL,resource_type varchar(80) NOT NULL,resource_id varchar(36) NOT NULL,payload jsonb NOT NULL,previous_hash varchar(64) NOT NULL,event_hash varchar(64) UNIQUE NOT NULL,source_version varchar(100) NOT NULL DEFAULT 'audit-chain@2.0.0',correlation_id varchar(36) NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),CONSTRAINT uq_audit_tenant_sequence UNIQUE(tenant_id,sequence));

-- Upgrade-safe defaults for databases created by the former Python backend.
ALTER TABLE roles ADD COLUMN IF NOT EXISTS created_at timestamptz NOT NULL DEFAULT now();
ALTER TABLE user_roles ADD COLUMN IF NOT EXISTS created_at timestamptz NOT NULL DEFAULT now();
ALTER TABLE tenants ALTER COLUMN created_at SET DEFAULT now();
ALTER TABLE roles ALTER COLUMN created_at SET DEFAULT now();
ALTER TABLE users ALTER COLUMN is_active SET DEFAULT true, ALTER COLUMN created_at SET DEFAULT now();
ALTER TABLE user_roles ALTER COLUMN created_at SET DEFAULT now();
ALTER TABLE invoices ALTER COLUMN status SET DEFAULT 'EXTRACTED', ALTER COLUMN source_version SET DEFAULT 'document-service@2.0.0', ALTER COLUMN created_at SET DEFAULT now(), ALTER COLUMN updated_at SET DEFAULT now();
ALTER TABLE invoice_files ALTER COLUMN created_at SET DEFAULT now();
ALTER TABLE account_files ALTER COLUMN category SET DEFAULT 'other', ALTER COLUMN description SET DEFAULT '', ALTER COLUMN tags SET DEFAULT '[]'::jsonb, ALTER COLUMN created_at SET DEFAULT now(), ALTER COLUMN updated_at SET DEFAULT now();
ALTER TABLE invoice_lines ALTER COLUMN created_at SET DEFAULT now();
ALTER TABLE extraction_runs ALTER COLUMN created_at SET DEFAULT now();
ALTER TABLE extracted_fields ALTER COLUMN created_at SET DEFAULT now();
ALTER TABLE field_corrections ALTER COLUMN source_version SET DEFAULT 'human-correction@2.0.0', ALTER COLUMN created_at SET DEFAULT now();
ALTER TABLE rule_results ALTER COLUMN created_at SET DEFAULT now();
ALTER TABLE reconciliation_runs ALTER COLUMN source_version SET DEFAULT 'reconciliation@2.0.0', ALTER COLUMN created_at SET DEFAULT now();
ALTER TABLE model_predictions ALTER COLUMN created_at SET DEFAULT now();
ALTER TABLE risk_assessments ALTER COLUMN source_version SET DEFAULT 'risk-aggregator@2.0.0', ALTER COLUMN created_at SET DEFAULT now();
ALTER TABLE review_tasks ALTER COLUMN status SET DEFAULT 'PENDING', ALTER COLUMN assigned_role SET DEFAULT 'accountant_lead', ALTER COLUMN source_version SET DEFAULT 'review-workflow@2.0.0', ALTER COLUMN created_at SET DEFAULT now();
ALTER TABLE review_decisions ALTER COLUMN source_version SET DEFAULT 'review-workflow@2.0.0', ALTER COLUMN created_at SET DEFAULT now();
ALTER TABLE audit_events ALTER COLUMN source_version SET DEFAULT 'audit-chain@2.0.0', ALTER COLUMN created_at SET DEFAULT now();
